# بطاقات الاستذكار: كل بطاقة (سؤال، جواب برقم الصفحة).
_FC = {
"الشريعة": [
 ("ما معنيا الشريعة في اللغة؟", "١. الطريقة المستقيمة ﴿ثُمَّ جَعَلْنَاكَ عَلَىٰ شَرِيعَةٍ مِّنَ الْأَمْرِ﴾. ٢. مشرعة الماء: مورد الشاربة (ص ١٥)."),
 ("ما المعنى العام للشريعة اصطلاحاً؟", "الأحكام التي سنّها الله لعباده عن طريق واحد من رسله، فتشمل كل الشرائع السماوية كشريعة موسى وعيسى (ص ١٥)."),
 ("ما المعنى الخاص للشريعة؟", "ما شرعه الله لعباده من الدين عن طريق نبيه محمد ﷺ: العقائد والعبادات والأخلاق والمعاملات ونظم الحياة (ص ١٦)."),
 ("ماذا يُراد بالشريعة عند الإطلاق؟ ولماذا؟", "الشريعة الإسلامية؛ لأنها الشريعة الخاتمة لكل الشرائع السماوية (ص ١٦)."),
 ("ما وجه الشبه بين الشريعة ومورد الماء؟", "كلاهما سبيل للحياة: الشريعة تحيي النفوس والعقول، والماء يحيي الأبدان (ص ١٦)."),
 ("لماذا وُصفت الشريعة بأنها «إسلامية»؟", "نسبة إلى الإسلام: الاستسلام لله تعالى والانقياد لأحكامه والرضا بقضائه (ص ١٦)."),
 ("ما الدليلان اللذان اتفق الجمهور على إلحاقهما بالقرآن والسنة؟", "الإجماع الشرعي والقياس (ص ١٦)."),
 ("ما القوتان المتنازعتان في الإنسان؟", "قوة الشهوة التي تدفعه إلى الشر، وقوة العقل التي تدعوه إلى الخير، والعقل وحده لا يقاوم الشهوة (ص ١٧)."),
 ("ما الضرورات الخمس التي تحفظها الشرائع؟", "حفظ الدين، والنفس، والنسل، والمال، والعقل (ص ١٨)."),
 ("فيم تختلف الشرائع المنزلة وفيم تتفق؟", "تختلف في الأحكام العملية التي تتغير بتغير الأزمان، وتتفق في العقائد (ص ١٨ - ١٩)."),
 ("ما الأحكام التي تشتمل عليها الشريعة؟", "اعتقادية (علم الكلام)، وتهذيبية (علم الأخلاق)، وعملية (علم الفقه) (ص ١٩)."),
 ("لماذا سُمّيت أمور الآخرة والملائكة والجن «السمعيات»؟", "لأنها أمور مغيبة لا يدركها الإنسان إلا عن طريق السماع من الأنبياء والمرسلين (ص ١٩)."),
 ("كيف يكون القرآن والسنة وحياً؟", "القرآن وحي باللفظ والمعنى، والسنة وحي بالمعنى دون اللفظ (ص ٢٠)."),
 ("اذكر خمس قواعد فقهية من خصائص الشريعة.", "المشقة تجلب التيسير، الضرر يزال، الضرر لا يزال بالضرر، يُتحمّل الضرر الخاص لدفع الضرر العام، الضرورات تبيح المحظورات (ص ٢١)."),
 ("ما الثابت وما المرن في الشريعة؟", "الثابت: أصول العقائد والأخلاق والمعاملات وما ثبت بالوحي، والمرن: ما بُني على المصلحة المتغيرة أو العرف (ص ٢٢)."),
 ("كيف يجعل التعليلُ الشريعةَ متسعة لكل واقعة؟", "إذا توفرت العلة في المسكوت عنه أخذ حكم المنصوص عليه، وهو القياس (ص ٢٢)."),
 ("ما الخصيصة التي هي نتيجة لكل ما سبقها من خصائص الشريعة؟", "صلاحيتها للتطبيق في كل زمان ومكان (ص ٢٣)."),
],
"علم الفقه": [
 ("ما معنيا الفقه في اللغة؟ وأيهما أخص؟", "العلم والفهم المطلق، وفهم غرض المتكلم من كلامه، والثاني أخص لأنه قدر زائد على مجرد وضع اللفظ (ص ٢٤)."),
 ("ما تعريف أبي حنيفة للفقه؟", "«معرفة النفس ما لها وما عليها»، فيشمل الاعتقاديات والوجدانيات والعمليات، ولذا سمى علم الكلام «الفقه الأكبر» (ص ٢٦)."),
 ("ما التعريف الجامع المشهور للفقه؟", "العلم بالأحكام الشرعية العملية المكتسبة من أدلتها التفصيلية (ص ٢٦)."),
 ("ما المراد بالأحكام الشرعية في التعريف؟", "خطابات الشارع المتعلقة بأفعال المكلفين على سبيل الاقتضاء أو التخيير أو الوضع (ص ٢٦ - ٢٧)."),
 ("عرّف الحكم التكليفي.", "خطاب الله تعالى المتعلق بأفعال المكلفين بالاقتضاء (طلب فعل أو ترك) أو التخيير (الإباحة) (ص ٢٧)."),
 ("عرّف الحكم الوضعي مع مثال.", "خطاب الله بجعل الشيء سبباً أو شرطاً أو مانعاً أو صحيحاً أو فاسداً، كجعل الطهارة شرطاً لصحة الصلاة والحيض مانعاً من الصوم (ص ٢٧)."),
 ("ما فائدة قيد «العملية» في تعريف الفقه؟", "إخراج الأحكام المتعلقة بالعقائد والأحكام المتعلقة بالأخلاق (ص ٢٧)."),
 ("ما المراد بـ«المكتسبة»؟", "المأخوذة عن طريق الاجتهاد والنظر في الأدلة (ص ٢٧)."),
 ("فرّق بين الأدلة الإجمالية والتفصيلية.", "الإجمالية: الكتاب والسنة والإجماع والقياس، والتفصيلية: الآيات والأحاديث الخاصة بالأحكام مثل ﴿وَأَقِيمُوا الصَّلَاةَ﴾ (ص ٢٧ - ٢٨)."),
 ("ما العلاقة بين الفقه والشريعة؟", "الفقه مختص بالعمليات وهو جزء من الشريعة، والشريعة أعم تشمله وتشمل أفعال القلوب وغيرها (ص ٢٧ - ٢٨)."),
 ("عدّد موضوعات علم الفقه السبعة.", "العبادات، المعاملات، العقوبات والجنايات، السير والجهاد، أحكام الأسرة، الدعاوى والبينات والقضاء (المرافعات)، السياسة الشرعية (ص ٢٨ - ٢٩)."),
 ("ما الكتب المؤلفة في السير؟", "السير الكبير والسير الصغير لمحمد بن الحسن الشيباني، والسير لأبي يوسف، والسير للأوزاعي، والرد على سير الأوزاعي لأبي يوسف (ص ٢٩)."),
 ("ما الكتب المؤلفة في السياسة الشرعية؟", "السياسة الشرعية لابن تيمية، والأحكام السلطانية للماوردي، والأحكام السلطانية للقاضي أبي يعلى الحنبلي (ص ٢٩)."),
 ("ماذا تُسمّى الدعاوى والبينات والقضاء والشهادات؟", "المرافعات (ص ٢٩)."),
 ("كيف قسّم الحنفية الفقه؟", "ثلاثة أقسام: العبادات، والمعاملات، والعقوبات، وأدرجوا الأنكحة في المعاملات (ص ٣٠)."),
 ("ما العبادات الخمس عند ابن عابدين؟", "الصلاة والزكاة والصوم والحج والجهاد (ص ٣٠)."),
 ("ما أرباع الفقه عند المالكية؟", "العبادات، النكاح وتوابعه، البيع وتوابعه، الأقضية وتوابعها (ص ٣٠ - ٣١)."),
 ("بم علّل البجيرمي ترتيب الشافعية؟", "العبادة أهمها لتعلقها بالدين، ثم المعاملة لشدة الحاجة، ثم المناكحة، ثم الجناية لأنها تقع غالباً بعد الفراغ من شهوتي البطن والفرج (ص ٣١)."),
 ("ما تقسيم الحنابلة؟", "خماسي: العبادات، المعاملات، الأنكحة، الجنايات، القضاء والخصومات (ص ٣١)."),
 ("علامَ اتفق الفقهاء في تقسيماتهم؟", "على تقديم قسم العبادات لأهميتها في حياة المسلم (ص ٣١ - ٣٢)."),
],
"القانون الوضعي": [
 ("ما الآراء في أصل كلمة القانون؟", "قيل: من اللاتينية (kanon) بمعنى المسطرة أو القاعدة، وقيل: رومية أو فارسية أو سريانية أو عبرية (ص ٣٤)."),
 ("عرّف القانون اصطلاحاً.", "مجموعة القواعد التي تنظم سلوك الأفراد في الجماعة، وتعمل السلطة العامة على تطبيقها بتوقيع العقاب على من يخالفها (ص ٣٤)."),
 ("ما المقصود بالقانون الوضعي؟", "مجموعة القواعد القانونية السائدة والمطبقة فعلاً في دولة معينة وزمن معين، مدونة أو غير مدونة (ص ٣٤ - ٣٥)."),
 ("ما التعزير؟", "عقوبة جرائم لم تنص الشريعة على عقوبتها، تُرك تقديرها للحاكم بما لا يخالف قواعد الشريعة العامة (ص ٣٥)."),
 ("لماذا تختلف القوانين الوضعية بين المجتمعات؟", "لاختلاف العادات والتقاليد والأعراف (ص ٣٦)."),
 ("كيف يُفرّق بين القاعدة الآمرة والمفسرة إذا لم تتضح عبارة النص؟", "من موضوع القاعدة: ما اتصل بالنظام العام والآداب فهو آمر أو ناهٍ، وما عداه مكمّل (ص ٣٨)."),
 ("ما القانون غير المكتوب؟", "القانون العرفي غير المقنن الذي لا يصدر عن السلطة التشريعية بل ينشأ تدريجياً في ضمير الجماعة (ص ٣٨)."),
 ("ما أهم تقسيمات القانون في الوقت الحاضر؟", "تقسيمه إلى قانون عام وقانون خاص من حيث طبيعة الروابط التي ينظمها (ص ٣٨)."),
 ("ما فروع القانون العام الأربعة؟", "الدولي العام، والدستوري، والإداري والمالي، والجنائي (ص ٣٩)."),
 ("بم يتفرع القانون الجنائي؟", "قانون العقوبات، وقانون الإجراءات الجنائية (ص ٤٠)."),
 ("ما الذي يلحق بالقانون التجاري؟", "القانون البحري والقانون الجوي (ص ٤١)."),
 ("كيف نشأ قانون العمل؟", "فرع حديث نسبياً نشأ بعد النهضة الصناعية رد فعل من العمال على جور شروط أرباب العمل، وكان قبلُ خاضعاً للقانون المدني (ص ٤١)."),
 ("لماذا يعد قانون المرافعات قانوناً شكلياً إجرائياً؟", "لأنه ينظم إجراءات التقاضي أمام المحاكم بشأن الحقوق التي تقررها قواعد القانون الخاص (ص ٤٢)."),
 ("هل القانون الدولي الخاص دولي حقاً؟", "لا، هو قانون وطني لكل دولة قواعده، بخلاف القانون الدولي العام الذي قواعده واحدة لجميع الدول (ص ٤٢)."),
 ("ما مصادر القانون الوضعي في الدول الإسلامية؟", "التشريع، وأحكام الفقه الإسلامي ومبادئ الشريعة، والعرف (ص ٤٢)."),
 ("ما المصادر الاحتياطية للقانون الدولي العام؟", "القضاء الدولي (محكمة العدل الدولية ومحاكم التحكيم)، وفقه كبار المؤلفين، ومبادئ العدالة والإنصاف (ص ٤٣)."),
],
"خصائص الفقه": [
 ("عدّد خصائص الفقه الإسلامي السبع.", "يرجع إلى الوحي، وازع الدين والأخلاق، الجزاء دنيوي وأخروي، علم تطبيقي، قبول التطور، النزعة الجماعية، تنظيم الحياة الخاصة والعامة (ص ٤٤ - ٤٧)."),
 ("بم يتقيد الفقيه إذا لم تساعفه النصوص؟", "باستلهام روح الشريعة ومبادئها وأصولها ومقاصدها (ص ٤٤)."),
 ("ما أمثلة تمهيد الشريعة لأحكامها بوازع الدين والأخلاق؟", "العبادات لتطهير النفس، وتحريم الربا لنشر التعاون وحماية المحتاجين، ومنع الغش والجهالة في العقود لإشاعة الثقة (ص ٤٤ - ٤٥)."),
 ("أين يظهر عنصر الاستقرار في الفقه؟", "في الأحكام التفصيلية الثابتة بالنص: الحدود والكفارات والعبادات والمواريث والمحرمات من النساء (ص ٤٥)."),
 ("أين يبرز عنصر التطور في الفقه؟", "في مبدأ الاجتهاد بالرأي في غير المنصوص بالقياس أو المصالح المرسلة (ص ٤٥ - ٤٦)."),
 ("بم تُقيَّد النزعة الجماعية في الفقه؟ مثّل.", "بعدم الإضرار بصاحب الحق؛ كحق الزوج في الطاعة مقيد بعدم الإضرار بالزوجة ﴿وَلَا تُمْسِكُوهُنَّ ضِرَارًا﴾ (ص ٤٦)."),
 ("ما الكتب التي حفلت بالمبادئ العامة في المعاملات؟", "الأشباه والنظائر لابن نجيم الحنفي، والأشباه والنظائر للسيوطي الشافعي، والفروق للقرافي (ص ٤٧)."),
 ("ما النظام الاجتماعي الذي لا نظير له في القوانين الوضعية؟", "نظام الزكاة، وامتدت الرعاية إلى المحتاجين من غير المسلمين (ص ٤٧)."),
],
"قبل البعثة وأسس التشريع": [
 ("ما حال الفرس والروم قبل البعثة؟", "أكبر دولتين أصيبتا بالفوضى والصراع الاجتماعي، والحروب بينهما مستعرة دائماً (ص ٥٣)."),
 ("ما الفضائل التي كانت متأصلة في العرب؟", "الكرم والشجاعة والمروءة والنجدة والوفاء بالعهد (ص ٥٤)."),
 ("ما قالت هند بنت عتبة عند البيعة على ألا يزنين؟", "«أو تزني الحرة؟!» دلالة على ندرته في الحرائر (ص ٥٤)."),
 ("اذكر أنكحة الجاهلية الباطلة.", "الاستبضاع، والبدل والمبادلة، والبغايا، والشغار، والرهط (ص ٥٥)."),
 ("ما سبب حرب البسوس وكم دامت؟", "ناقة، ودامت أربعين عاماً بين بكر وتغلب (ص ٥٥)."),
 ("ما الدليل على رضا الجاهليين بالجرائم وإن لم يرتكبها الجميع؟", "عدم إنكارها دليل على الرضا بها (ص ٥٥)."),
 ("ما الأمر الجاهلي الذي أقره النبي ﷺ وقضى به؟", "القسامة (ص ٥٥ - ٥٦)."),
 ("من أول من أدخل الوثنية على العرب؟", "عمرو بن لُحي الخزاعي، جاء بـ«هُبل» من الشام (ص ٥٧)."),
 ("كم بلغت الأصنام في جوف الكعبة وفنائها؟", "ثلاثمئة وستين وثناً (ص ٥٧)."),
 ("بم صوّر جعفر بن أبي طالب حال الجاهلية للنجاشي؟", "«نعبد الأصنام، ونأكل الميتة، ونأتي الفواحش، ونقطع الأرحام، ونسيء الجوار، يأكل القوي منا الضعيف» (ص ٥٨)."),
 ("ما الأسس الثلاثة التي بُنيت عليها أحكام الشريعة؟", "عدم الحرج، وقلة التكاليف، والتدرج في التشريع (ص ٦٠)."),
 ("ما نوعا المشقة؟ وأيهما رفعه الشارع؟", "معتادة يمكن تحملها لا يقصد رفعها، وزائدة تضيق بها الصدور وهي المرفوعة (ص ٦١)."),
 ("اذكر أربعة أمثلة لرفع الحرج.", "قصر الرباعية في السفر، والجمع، والفطر بعذر، والتيمم، ودرء الحدود بالشبهات، ودية الخطأ على العاقلة (ص ٦١ - ٦٢)."),
 ("ما مراحل تحريم الخمر؟", "﴿قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ﴾، ثم ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنتُمْ سُكَارَىٰ﴾، ثم ﴿فَاجْتَنِبُوهُ﴾ (ص ٦٣)."),
 ("ما عقوبة الزاني في صدر الإسلام؟ ثم إلامَ صارت؟", "الحبس في البيوت والإيذاء بالقول، ثم الرجم للمحصن (بالسنة) والجلد للبكر (بالقرآن) (ص ٦٣)."),
 ("لماذا شُرع استقبال بيت المقدس أولاً؟", "لاستمالة أهل الكتاب وبيان أن النبي ﷺ مصدق لما جاء به الأنبياء، حتى يستعدوا لتحويل القبلة (ص ٦٤)."),
],
"الوحي والقرآن": [
 ("ما حدود عصر الرسالة ومدته؟", "من البعثة بنزول الوحي إلى وفاته ﷺ سنة ١١هـ، نحو ٢٣ سنة: ١٣ بمكة و١٠ بالمدينة (ص ٦٥)."),
 ("لماذا كان عصر الرسالة أفضل العصور؟", "فيه نزل التشريع واكتمل وتم الدين ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾، وهو عصر التأسيس (ص ٦٥)."),
 ("متى نزل الوحي على النبي ﷺ؟", "وهو ابن أربعين سنة، يوم الاثنين من رمضان على الراجح (ص ٦٧)."),
 ("ما أول ما بُدئ به رسول الله ﷺ من الوحي؟", "الرؤيا الصالحة في النوم، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح (ص ٦٧ - ٦٨)."),
 ("ما أشد صور إتيان الوحي على النبي ﷺ؟", "أن يأتيه مثل صلصلة الجرس (ص ٦٩)."),
 ("ما صور الوحي الخمس؟", "الوحي المباشر (النفث في الروع)، والكلام من وراء حجاب، والوحي بواسطة جبريل، وتمثّل الملك رجلاً، وتكليم الله يقظة أو مناماً (ص ٧٠ - ٧١)."),
 ("في صورة من كان جبريل يتمثل كثيراً؟", "في صورة الصحابي دحية الكلبي (ص ٧٠)."),
 ("لماذا لم يقع التشريع إلا في العصر النبوي؟", "لأن مشرّع الأحكام هو الله، والوحي ينزل بها على الرسول ﷺ، وبوفاته انقطع الوحي (ص ٧٢)."),
 ("ما غرضا التشريع المكي؟", "إصلاح العقيدة، وتهذيب الأخلاق (ص ٧٣)."),
 ("لماذا لم يكن في مكة تشريع للمعاملات والعقوبات؟", "لقلة المسلمين وعدم تكوّن أمة أو وحدة اجتماعية مستقلة منهم (ص ٧٤)."),
 ("لماذا تعد الفترة المدنية فترة التشريع بمعناه الحقيقي؟", "لأنها فترة نشأة الفقه وتكوينه وتنظيم شؤون الفرد والجماعة والدولة (ص ٧٥)."),
 ("ما أشهر الاصطلاحات في المكي والمدني؟", "الزماني: المكي ما نزل قبل الهجرة، والمدني ما نزل بعدها ولو بمكة (ص ٧٧)."),
 ("كم السور المدنية والمكية والمختلف فيها؟", "المدنية عشرون، والمكية باتفاق اثنتان وثمانون، والمختلف فيها اثنتا عشرة (ص ٧٧)."),
 ("ما السورة المكية التي ذُكر فيها المنافقون؟", "العنكبوت؛ فكل سورة فيها ذكر المنافقين مدنية إلا العنكبوت (ص ٧٨)."),
 ("عرّف القرآن الكريم.", "كلام الله العربي المنزل على محمد ﷺ، المدوّن في المصاحف، المنقول بالتواتر، المتعبد بتلاوته، المتحدى بأقصر سورة منه، المبدوء بالفاتحة المختوم بالناس (ص ٧٩)."),
 ("هل ترجمة القرآن والقراءة الشاذة قرآن؟", "لا؛ الترجمة تفسير، والشاذة ما لم يُنقل بالتواتر كقراءة ابن مسعود «متتابعات» (ص ٧٩)."),
 ("ما مرحلتا نزول القرآن؟", "الأولى: من اللوح المحفوظ جملة إلى السماء الدنيا في ليلة القدر، والثانية: منجماً على النبي ﷺ في ٢٣ سنة (ص ٨٠ - ٨١)."),
 ("ما حكمة إنزال القرآن منجماً؟", "تقوية قلب النبي ﷺ ليحفظه، ووجود الناسخ والمنسوخ، والجواب عن الأسئلة والحوادث، والرحمة بالعباد في التدرج (ص ٨١ - ٨٢)."),
 ("ما قصة قدامة بن مظعون؟ وما دلالتها؟", "شرب الخمر محتجاً بآية ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا... جُنَاحٌ﴾ فبيّن ابن عباس سبب نزولها، وتدل على فائدة أسباب النزول في إزالة الإشكال (ص ٨٢ - ٨٣)."),
 ("فيمن نزلت آيتا الظهار واللعان؟", "الظهار في أوس بن الصامت، واللعان في هلال بن أمية (ص ٨٣)."),
 ("ما أدوات كتابة القرآن في العهد النبوي؟", "اللخاف (صفائح الحجارة)، والعسب (جريد النخل)، والأكتاف، والرقاع، والأقتاب، والأديم (ص ٨٤)."),
 ("هل ترتيب الآيات والسور توقيفي؟", "ترتيب الآيات توقيفي بلا خلاف، والسور فيه أقوال: اجتهادي، توقيفي، بالتفصيل، والخلاف لفظي (ص ٨٤ - ٨٥)."),
],
"السنة والاجتهاد": [
 ("عرّف السنة النبوية.", "ما صدر عن النبي ﷺ غير القرآن من قول أو فعل أو تقرير (ص ٨٦)."),
 ("لماذا تأتي السنة في المرتبة الثانية بعد القرآن؟", "القرآن مقطوع بثبوته جملة وتفصيلاً والسنة جملة لا تفصيلاً، والسنة تجوز روايتها بالمعنى، وقُصد بها تفسير القرآن (ص ٨٨)."),
 ("مثّل لتبيين السنة مجمل القرآن.", "﴿وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ﴾ مجمل في الأعداد والأوقات والنصاب، فبيّنته السنة «صلوا كما رأيتموني أصلي» (ص ٨٨ - ٨٩)."),
 ("مثّل لتخصيص السنة عموم القرآن.", "الظلم في ﴿وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ﴾ بيّنت السنة أنه الشرك (ص ٨٩)."),
 ("اذكر أحكاماً استقلت بها السنة.", "تحريم الجمع بين المرأة وعمتها أو خالتها، وميراث الجدة، وصدقة الفطر، والوتر، وكفارة انتهاك رمضان (ص ٨٩)."),
 ("ما مثال نسخ السنة للقرآن عند من يجيزه؟", "آية الوصية للوالدين والأقربين منسوخة بحديث «لا وصية لوارث» (ص ٨٩ - ٩٠)."),
 ("كيف بيّنت السنة حكم ميتة البحر؟", "بطريق الإلحاق: ألحقها بالحلال «هو الطهور ماؤه الحل ميتته» (ص ٩٠)."),
 ("عرّف الاجتهاد اصطلاحاً.", "استفراغ الفقيه الوسع ليحصل له ظن بحكم شرعي (ص ٩٢)."),
 ("متى لا يقال إن الحكم مبني على الاجتهاد؟", "إذا نصت الأدلة عليه صراحة بلا حاجة إلى بذل جهد (ص ٩٣)."),
 ("ما الدليل العقلي على مشروعية الاجتهاد؟", "الوقائع لا تنحصر والأدلة منحصرة، فلا بد من الاجتهاد وإلا تُرك الناس لأهوائهم (ص ٩٣ - ٩٤)."),
 ("ما الراجح في اجتهاد النبي ﷺ؟", "يجوز له الاجتهاد فيما لا نص فيه، وقد اجتهد في كثير من الوقائع، واجتهاده مستند إلى الوحي (ص ٩٥)."),
 ("ما الذي يصدر عن النبي ﷺ ولا يعد تشريعاً؟", "ما سبيله التجربة والخبرة كالزراعة والطب، وما سبيله التدبير الإنساني كتوزيع الجيوش (ص ٩٥)."),
 ("ما الحكمة من ترك النص على حكم أسرى بدر؟", "أن يدرّب الله نبيه وأصحابه على الاجتهاد (ص ٩٧)."),
 ("بم صوّب النبي ﷺ حكم سعد بن معاذ في بني قريظة؟", "«لقد حكمت فيهم بحكم الله» (ص ٩٨)."),
 ("ما قال ﷺ للصحابيين المتيممين؟", "للذي لم يعد: «أصبت السنة وأجزأتك صلاتك»، وللذي أعاد: «لك الأجر مرتين» (ص ٩٨)."),
 ("لماذا لا يعد الاجتهاد مصدراً للتشريع في العصر النبوي؟", "لأن مرجعه الوحي: اجتهاد النبي ﷺ يقره الوحي أو ينبهه، واجتهاد الصحابة مرجعه إلى السنة (ص ١٠٠)."),
],
"عصر الصحابة": [
 ("ما حدود عصر الصحابة؟", "من وفاة النبي ﷺ سنة ١١هـ إلى تولي معاوية الخلافة سنة ٤١هـ (ص ١٠٨)."),
 ("لماذا يُسمّى عصر الصحابة «عصر التفسير التشريعي»؟", "لصدور آراء كثيرة عن رؤوس الصحابة في تفسير نصوص الأحكام صارت مرجعاً تشريعياً، وفتح أبواب الاستنباط فيما لا نص فيه (ص ١٠٩)."),
 ("ما سبب جمع القرآن في عهد أبي بكر؟", "استشهاد كثير من القراء في موقعة اليمامة، فأشار عمر بجمعه خشية ذهابه (ص ١١٠)."),
 ("لماذا اختير زيد بن ثابت لجمع القرآن؟", "لأنه ألزم الصحابة لمجلس رسول الله ﷺ وأحفظهم للقرآن، وكان يكتب الوحي، شاب عاقل لا يُتّهم (ص ١١٠ - ١١١)."),
 ("أين استقرت صحف أبي بكر؟", "عند أبي بكر حتى توفي، ثم عند عمر حياته، ثم عند حفصة بنت عمر (ص ١١١)."),
 ("ما سبب نسخ المصاحف في عهد عثمان؟", "اختلاف الناس في القراءة، وقول حذيفة: «أدرك الأمة قبل أن يختلفوا اختلاف اليهود والنصارى» (ص ١١١)."),
 ("بم أوصى عثمان لجنة النسخ عند الاختلاف؟", "أن يكتبوه بلسان قريش لأنه إنما نزل بلسانهم (ص ١١٢)."),
 ("ما «مصحف الإمام»؟", "المصحف الذي أبقاه عثمان لنفسه بالمدينة بعد إرسال المصاحف إلى الأمصار (ص ١١٢)."),
 ("كيف يُجمع بين النهي عن كتابة الحديث والإذن فيه؟", "النهي خاص بوقت النزول، أو بكتابته مع القرآن، أو منسوخ بالإذن (وهو أقربها)، أو لمن خُشي اتكاله على الكتابة (ص ١١٤)."),
 ("ما الصحيفة الصادقة؟", "صحيفة عبد الله بن عمرو بن العاص: «هذه ما سمعت من رسول الله ﷺ ليس بيني وبينه أحد» (ص ١١٥)."),
 ("ما الذي كان في صحيفة علي رضي الله عنه؟", "أسنان الإبل وشيء من الجراحات، وكانت معلقة في سيفه (ص ١١٥)."),
 ("مثّل لتشدد أبي بكر في قبول السنة.", "في ميراث الجدة طلب شاهداً مع المغيرة بن شعبة، فشهد محمد بن مسلمة فأنفذه (ص ١١٦)."),
 ("كيف كان علي يتوثق من الرواية؟", "كان يستحلف الراوي على روايته حتى تُقبل منه (ص ١١٧)."),
 ("لماذا عدل عمر عن كتابة السنن؟", "ذكر قوماً قبلنا كتبوا كتباً فأكبوا عليها وتركوا كتاب الله، فقال: «لا ألبس كتاب الله بشيء أبداً» (ص ١١٧)."),
 ("ما مصادر التشريع في عصر الصحابة؟", "الكتاب، والسنة، والإجماع، والرأي الذي سُمّي القياس بعد ذلك (ص ١٣٠)."),
 ("لماذا كان الإجماع ميسوراً زمن أبي بكر وعمر؟", "لوجود المجتهدين بالمدينة؛ إذ لم يسمح لهم عمر بالخروج إلا للضرورة (ص ١٣١)."),
 ("كيف أخذ عمر الحكم من معقول النص في العاقلة؟", "رأى أن المسؤولية لمن تكون بهم النصرة والمعونة، فجعل العاقلة على أهل الديوان وإن لم يكونوا أقارب (ص ١٣١ - ١٣٢)."),
 ("لماذا لم يقطع عمر يد السارق عام المجاعة؟", "لشبهة الاضطرار، عملاً بمبدأ إباحة المحرم للضرورة (ص ١٣٢)."),
 ("ما قضاء ابن مسعود في المفوَّضة؟", "لها مهر نسائها لا وكس ولا شطط، ولها الميراث، وعليها العدة أربعة أشهر وعشراً، ووافق قضاء النبي ﷺ في بروع بنت واشق (ص ١٣٣)."),
 ("لماذا لم يفترض الصحابة المسائل؟", "رأوا الاشتغال بما لم يقع عبثاً، مع خوف الخطأ، والانشغال بالسياسة، وعدم تدوين المصادر (ص ١٣٣ - ١٣٤)."),
 ("ما خصائص الفقه في عصر الصحابة؟", "نوازل جديدة، واتباع المنهج النبوي، وقلة التفريعات، وصدور الفتوى عن تبصر وحكمة، ووقوع الإجماع (ص ١٣٥)."),
 ("كيف تعلم الصحابة القرآن؟", "قال ابن مسعود: «كنا لا نتجاوز عشر آيات حتى نعلم ما بهن ونعمل بهن» (ص ١٣٧)."),
 ("ما الأحكام الزاجرة التي استحدثها الصحابة؟", "إمضاء عمر الطلاق الثلاث بلفظ واحد، وتضمين الصنّاع (ص ١٣٩)."),
],
"فقهاء الصحابة واختلافهم": [
 ("لماذا سُمّي فقهاء الصحابة «القراء»؟", "لأن العرب أمة أمية فاختص من كان قارئاً للكتاب بهذا الاسم (ابن خلدون) (ص ١١٩)."),
 ("كم عدد من حُفظت عنهم الفتوى من الصحابة؟", "مائة ونيف وثلاثون نفساً ما بين رجل وامرأة (ابن القيم) (ص ١١٩)."),
 ("من المكثرون من الفتوى من الصحابة؟", "عمر، وعلي، وابن مسعود، وعائشة، وزيد بن ثابت، وابن عباس، وابن عمر (ص ١١٩ - ١٢٠)."),
 ("من المقدَّمون في الفقه من الصحابة؟", "عبد الله بن مسعود، وعبد الله بن عمر، وعبد الله بن عباس، وزيد بن ثابت (ص ١٢٠)."),
 ("فيم غلب زيد بن ثابت الناس؟", "في الفرائض والقرآن (قاله الشعبي) (ص ١٢٠)."),
 ("بم فسّر ابن عباس سورة النصر أمام عمر؟", "هو أجل رسول الله ﷺ أعلمه له، فقال عمر: ما أعلم منها إلا ما تقول (ص ١٢١)."),
 ("لماذا بكى عمر عند نزول آية الإكمال؟", "قال: «ما بعد الكمال إلا النقصان» مستشعراً نعي النبي ﷺ، فلم يعش بعدها إلا ٨١ يوماً (ص ١٢٢)."),
 ("ما معنى «التخوف» في ﴿أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ﴾؟", "التنقّص، كما أجاب شيخ من هذيل عمرَ واستشهد بشعر العرب (ص ١٢٢ - ١٢٣)."),
 ("ما أقوال الصحابة في «القرء»؟", "الأطهار: عائشة وزيد بن ثابت وابن عمر، والحيض: عمر وابن مسعود ونفر من الصحابة (ص ١٢٤)."),
 ("ما قول عثمان وابن عباس في الجمع بين الأختين بملك اليمين؟", "أباحاه وقالا: «أحلّتهما آية وحرّمتهما آية»، والجمهور على التحريم (ص ١٢٥)."),
 ("ما الذي لم يعلمه العباس وفاطمة حتى طلبا الميراث؟", "قول النبي ﷺ: «لا نُورث ما تركنا صدقة» (ص ١٢٥ - ١٢٦)."),
 ("ما المسألة المشرَّكة؟ وبم قضى فيها عمر؟", "اجتماع الإخوة الأشقاء مع ولد الأم ولا يبقى للأشقاء شيء، فشرّكهم عمر مع ولد الأم في الثلث بالسوية (ص ١٢٦ - ١٢٧)."),
 ("ما رأي ابن عباس في الرَّمَل في الطواف؟", "فعله النبي ﷺ لسبب (قول المشركين: أوهنتهم حمى يثرب) فذهب بذهاب سببه وليس بسنة (ص ١٢٧)."),
 ("ما المسألتان الغرّاويتان؟ وما قول عمر وابن عباس؟", "زوج وأب وأم، أو زوجة وأم وأب: للأم ثلث الباقي عند عمر، وثلث التركة مطلقاً عند ابن عباس (ص ١٢٧)."),
 ("لماذا كان اختلاف الصحابة قليلاً بالنسبة لمن بعدهم؟", "لأخذهم بالشورى، وتيسّر الإجماع في عصرهم، وقلة الرواية (ص ١٢٨)."),
],
"عصر التابعين": [
 ("ما حدود عصر التابعين؟", "من تنازل الحسن لمعاوية عام ٤١هـ إلى ظهور الضعف على الدولة نحو ١٣٢هـ (ص ١٤٥)."),
 ("عرّف التابعي عند المحدثين.", "من لقي الصحابي وإن لم تطل صحبته، وقيل: لا بد من طول الصحبة (ص ١٤٦)."),
 ("ما مصادر التابعين في التشريع؟", "مصادر الصحابة عدا الإجماع، وزادوا عليها أقوال الصحابة (ص ١٤٦)."),
 ("من أئمة التابعين في الأمصار؟", "المدينة: ابن المسيب وسالم، مكة: عطاء، الكوفة: النخعي والشعبي، البصرة: الحسن، اليمن: طاووس، الشام: مكحول (ص ١٤٧)."),
 ("ما مذهب الحجازيين في دية المرأة؟", "كدية الرجل حتى تبلغ الثلث، فما زاد فعلى النصف، ومذهب العراقيين: نصف دية الرجل ابتداءً (ص ١٤٩)."),
 ("بم رجّح أبو حنيفة روايته على رواية الأوزاعي؟", "بفقه الرواة: «كان حماد أفقه من الزهري، وكان إبراهيم أفقه من سالم... وعبد الله هو عبد الله» (ص ١٤٩ - ١٥٠)."),
 ("من أجاز التسعير من التابعين؟", "سعيد بن المسيب، وربيعة، ويحيى بن سعيد الأنصاري، إذا دعت مصلحة الجماعة (ص ١٥٠)."),
 ("بم اتسم فقه التابعين؟", "بعدم تهيّب الفتيا، والتجديد ومراعاة الأعراف والمصالح، وتعرف علل الأحكام ومقاصدها (ص ١٥١)."),
 ("ما أسباب اتساع دائرة الاختلاف في عصر التابعين؟", "تفرق العلماء في الأمصار، وظهور الفرق، واختلاف العادات، وانقسام العلماء إلى أهل حديث وأهل رأي (ص ١٥١ - ١٥٢)."),
],
"المدرستان": [
 ("لماذا برزت مدرسة المدينة؟", "لأنها موطن الرسول ﷺ وفيها قبره، ومقام جمهور الصحابة، وعاصمة الخلافة حتى عهد عثمان (ص ١٥٣)."),
 ("كم نزل الكوفة من الصحابة كما قال النخعي؟", "ثلاثمائة من أصحاب الشجرة وسبعون من أهل بدر (ص ١٥٣)."),
 ("من إمام مدرسة المدينة؟ وما لقبه؟", "سعيد بن المسيب القرشي المخزومي، «فقيه الفقهاء»، توفي سنة ٩٣هـ (ص ١٥٤)."),
 ("من الفقهاء السبعة؟", "ابن المسيب، وعروة بن الزبير، والقاسم بن محمد، وخارجة بن زيد، وأبو بكر بن عبد الرحمن، وسليمان بن يسار، وعبيد الله بن عبد الله بن عتبة (ص ١٥٥)."),
 ("من مؤسس مدرسة الكوفة؟", "عبد الله بن مسعود الهذلي، معلم أهل الكوفة وقاضيها، توفي بالمدينة سنة ٣٢هـ (ص ١٥٥)."),
 ("ما قول ابن مسعود في اتباع عمر؟", "«لو سلك الناس وادياً وشعباً وسلك عمر وادياً وشعباً لسلكت وادي عمر وشعبه» (ص ١٥٥)."),
 ("من أشهر تلاميذ ابن مسعود؟", "علقمة، والأسود، ومسروق، وعبيدة السلماني، وشريح، والحارث الأعور، وإبراهيم النخعي (ص ١٥٥ - ١٥٦)."),
 ("على أي قاعدة مهّد أهل الكوفة الفقه؟", "قاعدة التخريج: تخريج جواب المسائل على أقوال أصحابهم لما عندهم من الفطانة والحدس (ص ١٥٦)."),
 ("لماذا قلّت الأحاديث عند أهل الكوفة؟", "لشيوع الوضع في العراق وتهيّبهم من رواية الحديث، ووصية عمر: «أقلّوا الرواية» (ص ١٥٧)."),
 ("فيم كان الخلاف بين المدرستين حقيقة؟", "في التلقي مع تباين البيئة والأعراف، لا في مصادر التشريع، وأوجه الاتفاق أكثر (ص ١٥٨)."),
],
"الرواية والتدوين": [
 ("هل اشترط التابعون عدداً لقبول الخبر؟", "لا، قبلوا ممن توافرت فيه شروط التحمل والأداء والعدالة (ص ١٥٩)."),
 ("ما أسباب شيوع رواية الحديث؟", "اتساع الفتوحات، وتفرق علماء الصحابة، والرحلة، وظهور متعلمي الموالي، وكثرة الفتن، والحوادث الجديدة (ص ١٦٠ - ١٦١)."),
 ("من الموالي المرافقون لابن عباس وابن عمر وأبي هريرة؟", "عكرمة مع ابن عباس، ونافع مع ابن عمر، وعبد الرحمن بن هرمز مع أبي هريرة (ص ١٦١)."),
 ("ما أسباب الوضع في الحديث؟", "العداوة الدينية، والتساهل في الترغيب والترهيب، والتعصب المذهبي، والتعالي في القبول، والتكسب من الأمراء (ص ١٦٢)."),
 ("من رأس العداوة الدينية في الوضع؟", "عبد الله بن سبأ اليهودي، تستر بالإسلام وحب آل البيت (ص ١٦٢)."),
 ("ماذا زاد غياث بن إبراهيم في الحديث؟ ولماذا؟", "زاد «أو جناح» في «لا سبق إلا في خف أو نصل» لأن المهدي يحب اللعب بالحمام (ص ١٦٢ - ١٦٣)."),
 ("ما علامات الوضع في المتن؟", "ركاكة اللفظ مع ركاكة المعنى وفساده، وإدراج عبارات يستحيل صدورها عن النبي ﷺ (ص ١٦٣)."),
 ("ما أثر شيوع الرواية في الفقه؟", "الاهتمام بصحة الحديث، واتساع الخلاف، وافتراض المسائل فانتقل الفقه من الواقعية إلى الفرض والتقدير (ص ١٦٤)."),
 ("متى بدأ التدوين الرسمي للسنة؟", "في عهد عمر بن عبد العزيز (بويع صفر ٩٩هـ) على رأس المائة الأولى (ص ١٦٥)."),
 ("إلى من كتب عمر بن عبد العزيز في جمع السنن؟", "إلى علماء الأمصار وعماله، وإلى أبي بكر بن حزم (ما عند عمرة والقاسم)، وإلى الزهري (ص ١٦٥ - ١٦٦)."),
 ("ما طريقة الزهري في التدوين؟", "جمع أحاديث كل موضوع في مؤلف خاص مختلطة بأقوال الصحابة وفتاوى التابعين (ص ١٦٦)."),
 ("ما جهود التابعين في خدمة السنة؟", "الحفظ والسماع والتثبت، والحلقات والصحف، ونقد الرجال، والاهتمام بالإسناد، ونقد المتن (ص ١٦٦ - ١٦٩)."),
 ("لماذا كان كلام التابعين في نقد الرجال قليلاً؟", "لأن أكثر التابعين عدول، ولا يكاد يوجد في القرن الأول ضعيف إلا الواحد بعد الواحد (ص ١٦٨)."),
 ("بم وصف الحسن البصري حفظهم للكتب؟", "«إن لنا كتباً نتعاهدها» (ص ١٦٩)."),
],
}

